__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"GUIDE_TOPICS",{enumerable:!0,get:function(){return t}});const t=[{id:'timestamps',title:'Timestamps & countdowns',summary:'Local time, date styles, ranges, and :R.',tool:'timestamp',toolLabel:'Open Timestamp tool',sections:[{title:'What a timestamp means',body:'A Discord timestamp sends an instant, not a fixed timezone label. Its number is Unix time in whole seconds since January 1, 1970 UTC. Discord displays that same instant in each reader\u2019s local timezone. The letter chooses how it looks; it does not change the instant.'},{title:'Choose the moment safely',body:'In Timestamp, type the date and 24-hour time, or tap the calendar and clock. Formatr interprets these in your device\u2019s local timezone, shown below the fields. Invalid dates and local times skipped by daylight saving are rejected. Now resets to the current time; the signed shortcuts adjust the selected moment.'},{title:'Understand the styles',body:'t: short time \xb7 T: time with seconds\nd: numeric date \xb7 D: written date\nf: date and time \xb7 F: full date with weekday\ns: numeric date and time \xb7 S: numeric date and time with seconds\nR: relative time\nNo flag: the default date-and-time style, like f. Capitalization matters. These use the reader\u2019s locale, so ordering and 12/24-hour display can differ.'},{title:'Countdown before, elapsed time after',body:':R shows wording such as \u201cin 2 hours\u201d before a target and \u201c2 hours ago\u201d afterward. It updates in Discord, but it is not a precise second-by-second stopwatch. Tick Add countdown / elapsed time to pair it with other styles. Existing :R tags are not duplicated.',example:'<t:SECONDS:F> (<t:SECONDS:R>)',exampleNote:'Structure example only: SECONDS must be actual Unix seconds. Use the tool to generate a valid tag.'},{title:'End-only targets and ranges',body:'End-only countdown uses just your End moment\u2014no Start is copied. Range Mode instead lets both range cards share one editable End, which must be after Start. End shortcuts in Range Mode calculate from Start. With the relative-time checkbox on, range countdowns target End; without it, a range is just two dates or times.'},{title:'Copy, then check',body:'Copy generates the real number for the chosen moment. A full date plus :R is useful for an event announcement: readers see both the appointment and how far away it is. A code-wrapped teaching example deliberately stays literal in Discord rather than turning into a countdown.'}]},{id:'markdown',title:'Markdown & code blocks',summary:'Text styles, headings, quotes, lists, and links.',tool:'markdown',toolLabel:'Open Markdown tool',sections:[{title:'What Markdown does',body:'Markdown is plain text with markers that Discord interprets as formatting. In the Markdown tool, type once at the top. Each format shows a Discord-style preview and the raw syntax that Copy or Add to draft will use. Examples are labeled and cannot be copied until the required fields are filled.'},{title:'Style a word or sentence',body:'Markers go on both sides of the text. Spoilers conceal content until the reader reveals it. Inline code displays a short literal snippet instead of interpreting its formatting.',example:'**bold**   *italic*   __underline__\n~~strikethrough~~   ||spoiler||   `inline code`'},{title:'Headings and small subtext',body:'Put #, ##, or ### at the beginning of a line for large, medium, or small headings. Use -# for small muted subtext. Keep a space between the marker and the words. The tool applies these line prefixes to each non-empty line.',example:'# Main heading\n## Section heading\n### Small heading\n-# A short supporting note'},{title:'Quotes and lists',body:'> quotes a line; >>> quotes the remaining message, including later paragraphs. For bullet or numbered lists, type each item on its own line. Formatr adds a bullet or the next number and preserves blank lines.',example:'> quoted line\n\n- First item\n- Second item\n\n1. First step\n2. Next step'},{title:'Code blocks and language chips',body:'Use a code block for multiple lines or a literal code example. Tap Code Block to choose none, yaml, json, js, or diff. None omits the language label. Highlighting depends on the language and client. Remove existing triple backticks before using the wrapper so they do not close the block early.',example:'```json\n{"status": "ok"}\n```'},{title:'Links and embed suppression',body:'Fill the URL field for link formats. A masked link uses your single-line text as the clickable label. Angle brackets around a URL suppress its large embed; they do not make the destination private or safe.',example:'[Visit website](https://example.com)\n<https://example.com>'}]},{id:'ansi',title:'ANSI colors & modifiers',summary:'Foreground, background, bold, and underline.',tool:'ansi',toolLabel:'Open ANSI color tool',sections:[{title:'What ANSI means here',body:'ANSI escape sequences are invisible control characters inside a code block labeled ansi. They tell compatible Discord clients how to color and style the text. This is not ordinary Markdown text color, and support can vary by client.'},{title:'Build your style',body:'Enter the text, choose a foreground color, and optionally choose a background. None removes the background. Bold / Bright and Underline can be combined; Normal clears both modifiers without changing your chosen colors. Swatches and the preview use the supplied dark-theme palette.'},{title:'Understand the codes',body:'0 resets formatting. 1 enables bold/bright; 4 enables underline. Foreground codes run from 30 through 37; background codes run from 40 through 47. The generator starts from a reset, applies your settings, and adds a final reset so the style does not carry onward.'},{title:'Use Copy rather than typing ESC',body:'The readable syntax displays \\u001b so invisible characters can be understood. Typing those six characters does not create a real escape character. Copy ANSI block and Add to draft insert the actual ESC characters and complete ansi fence. Existing escape codes or triple-backtick fences in the input must be removed first.'},{title:'If colors do not appear',body:'Check that the code block is labeled ansi and that you used the tool\u2019s Copy action. The staging preview illustrates the selected style; it cannot force another Discord client to render ANSI. Avoid relying on color alone to communicate important information, and check foreground/background contrast.'}]},{id:'emoji',title:'Emoji & custom IDs',summary:'Standard emoji, custom syntax, and your vault.',tool:'emoji',toolLabel:'Open Emoji tool',sections:[{title:'Standard versus custom',body:'Standard Unicode emoji are characters you can enter from your device keyboard or the Common emoji category. Their artwork varies by device. The shared grid groups channel accents, status badges, reaction numbers, and common emoji: tap any tile to copy, or add the last copied item to your draft. Custom Discord emoji instead use a name and numeric ID associated with an uploaded image.'},{title:'Read the custom syntax',body:'A static custom emoji starts with <: and an animated one starts with <a:. The name is a readable label; the numeric ID identifies the image. Do not remove the brackets, colons, or animation marker.',example:'<:name:EMOJI_ID>\n<a:name:EMOJI_ID>',exampleNote:'Structure examples only: EMOJI_ID must be the emoji\u2019s real numeric ID.'},{title:'Grab and save an ID',body:'Paste complete custom emoji markup into the ID grabber. It checks for a 2\u201332 character name using letters, numbers, and underscores, plus a 17\u201321 digit ID. Valid entries show their name, ID, animated/static form, and an image preview when available. You can paste several tokens; duplicates are shown once. Save useful entries to the local vault, or copy/insert the original token. Validation checks syntax, not whether the image exists or your account can use it.'},{title:'Why an emoji may stay as text',body:'Knowing an ID does not grant permission to use that emoji everywhere. Rendering depends on Discord availability, server access, and account permissions. Formatr cannot bypass those rules. Check the final message in Discord if the emoji is important.'}]},{id:'saved',title:'Drafts, saved text & macros',summary:'Keep writing and reuse responses with placeholders.',sections:[{title:'Active draft versus saved drafts',body:'The composer\u2019s active text autosaves locally, so visiting another tab or reopening the app can restore it. Save Draft keeps a named entry in Saved. Opening a saved draft lets you continue working on it. Clearing the active composer is separate from deleting saved entries.'},{title:'What a macro is',body:'A macro is a reusable response. Plain saved text copies immediately. Add simple named tags in curly brackets when you want to fill in a person, channel, or other detail at copy time.',example:'Hi {name}, please check {channel} for the latest update.'},{title:'Fill before copying',body:'Tags use letters, numbers, and underscores, such as {name} or {event_date}. Repeated tags share the same answer. Formatr prompts for the detected tags and substitutes your answers before copying. Review those values so you do not send an incomplete response.'},{title:'Where your writing lives',body:'Drafts, macros, and saved custom emoji stay in local device storage, not a synced account. Safari storage and the installed app are separate. Clearing site/app data, uninstalling the app, or deleting saved content can remove local writing. Keep another copy of anything irreplaceable.'}]},{id:'limits',title:'Message limits & safe copying',summary:'Character totals, warnings, and clipboard behavior.',sections:[{title:'Standard and Nitro',body:'Choose Standard for a 2,000-character message limit or Nitro for 4,000. The selection changes Formatr\u2019s counter and warning thresholds; it does not upgrade your Discord account. Use the tier that applies to the account you will post with.'},{title:'Read the colors',body:'Standard is green through 1,850, amber from 1,851 to 1,999, and red at 2,000 or more. Nitro is green through 3,700, amber from 3,701 to 3,999, and red at 4,000 or more. Red marks the full-limit safety boundary, not a locked editor.'},{title:'Why the editor keeps accepting text',body:'The counter is advisory. You can keep drafting, editing, and copying even above a single-message limit. Formatr does not automatically split the post. Shorten or divide it before sending if necessary. The full total is shown rather than an \u201cover by\u201d amount.'},{title:'Count the raw message',body:'Formatting markers, URLs, timestamp tags, and custom emoji tokens all contribute to raw message length even if the rendered result looks short. Some emoji contain multiple underlying characters. Check the raw version near the limit rather than judging by appearance alone.'},{title:'What Copy confirms',body:'Copy uses message syntax, not a screenshot or styled clipboard document. Before writing the clipboard, smart single quotes and acute accents become ASCII backticks, smart double quotes become straight double quotes, and Windows line endings become LF. This also changes curly apostrophes in ordinary sentences, but leaves your editor and saved text untouched. A brief color flash and checkmark indicate successful copying. Haptics depend on device/browser support and the Settings switch. A lack of vibration in Safari does not by itself mean copying failed. Formatr never sends the message to Discord for you.'}]},{id:'previews',title:'Previews, links & device differences',summary:'Know what the preview can\u2014and cannot\u2014guarantee.',sections:[{title:'Raw versus rendered',body:'Raw mode shows your draft text and formatting markers. Rendered mode illustrates supported formatting. Both refer to the same draft, and switching between them does not rewrite it. Copy normalizes smart punctuation and Windows line endings without changing the draft itself. Use raw mode when checking syntax or character totals.'},{title:'External link cards',body:'With link previews on, supported external links appear as informational cards near their position in the draft. A YouTube card is not an embedded video player here. Discord may use different titles, images, placement, or embed availability depending on the provider and message.'},{title:'No broken-looking placeholder players',body:'The app uses a clean title card rather than pretending to load a video it cannot play. Turning previews off leaves the link itself. The copied message is still the URL; it does not contain Formatr\u2019s preview card.'},{title:'What can differ in Discord',body:'Fonts, themes, emoji artwork, date locale, link metadata, and ANSI support can vary. Custom emoji need appropriate access. Formatr\u2019s previews are guidance, not a guarantee that every client or server renders identically. Review an important post in Discord before sending it.'},{title:'Media and preferences',body:'Once the app owner configures a KLIPY key, Media opens on Trending GIFs. Enter a phrase in Search KLIPY and submit to search. Scroll for more pages, or refresh for a new feed. Copy link copies the exact media URL; Add to composer appends it to your draft. No message is posted to Discord. Search results are temporary; links you add to drafts are saved with those drafts. Settings holds shared preferences such as link previews, message tier, Safe Search, and haptics. Browser vibration only works where supported; iPhone Safari may provide visual feedback without vibration.'},{title:'KLIPY safety and privacy',body:'Searches and media loads go directly from your device to KLIPY, with an anonymous device identifier for selections. Formatr does not save your search history or create a media cache. Safe Search starts on and requests KLIPY\u2019s High filter; off requests its Off filter. Provider moderation and account-level rules still apply, and no filter guarantees every result. Testing-mode keys have a 100-request-per-hour allowance, so searches run when submitted rather than on every keystroke.'}]}]},1411,[]);
